#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<math.h>
#define D 768
#define H 12
#define L 12
#define V 50257
#define N 1024
#define FC 3072
#define M 50000
#define HD 64
char m1[M][48],m2[M][48];
int l1[M],l2[M],vl[V],bid[256];
char voc[V][64];
float*C,*lw[L][12],*lf_b,*lf_g,*we,*pe,*x,*kc[L],*vc[L];
int isA(int c){return(c>='a'&&c<='z')||(c>='A'&&c<='Z');}
int isD(int c){return c>='0'&&c<='9';}
int isS(int c){return c==' '||c=='\t'||c=='\n'||c=='\r';}
void benc(int b,char*s,int*l){
 int cp;
 if((b>=33&&b<=126)||(b>=161&&b<=172)||(b>=174&&b<=255))cp=b;
 else if(b<=32)cp=256+b;
 else if(b==127)cp=289;
 else if(b<=160)cp=290+b-128;
 else cp=323;
 if(cp<128){s[0]=cp;s[1]=0;*l=1;}
 else{s[0]=0xC0|(cp>>6);s[1]=0x80|(cp&0x3F);s[2]=0;*l=2;}
}
void load_bpe(char*fn){
 int n=0,i;
 for(i=33;i<=126;i++)bid[i]=n++;
 for(i=161;i<=172;i++)bid[i]=n++;
 for(i=174;i<=255;i++)bid[i]=n++;
 for(i=0;i<=32;i++)bid[i]=n++;
 bid[127]=n++;
 for(i=128;i<=160;i++)bid[i]=n++;
 bid[173]=n++;
 for(i=0;i<256;i++){int l;benc(i,voc[bid[i]],&l);vl[bid[i]]=l;}
 FILE*f=fopen(fn,"r");
 char line[128];
 fgets(line,128,f);
 for(int r=0;r<M;r++){
  fgets(line,128,f);
  int l=strlen(line);
  if(l>0&&line[l-1]=='\n')line[l-1]=0;
  int sp=0;while(line[sp]&&line[sp]!=' ')sp++;
  memcpy(m1[r],line,sp);m1[r][sp]=0;l1[r]=sp;
  int rl=strlen(line+sp+1);
  memcpy(m2[r],line+sp+1,rl+1);l2[r]=rl;
  memcpy(voc[256+r],m1[r],l1[r]);
  memcpy(voc[256+r]+l1[r],m2[r],l2[r]+1);
  vl[256+r]=l1[r]+l2[r];
 }
 fclose(f);
}
void bpe(char*s,int sl,int*out,int*no){
 char tk[256][64];
 int tl[256],id[256],nt=0;
 for(int i=0;i<sl;i++){benc((unsigned char)s[i],tk[nt],&tl[nt]);id[nt]=bid[(unsigned char)s[i]];nt++;}
 for(;;){
  int f=0;
  for(int r=0;r<M&&!f;r++)
   for(int i=0;i<nt-1;i++)
    if(tl[i]==l1[r]&&tl[i+1]==l2[r]&&!memcmp(tk[i],m1[r],tl[i])&&!memcmp(tk[i+1],m2[r],tl[i+1])){
     memcpy(tk[i]+tl[i],m2[r],l2[r]+1);tl[i]+=l2[r];id[i]=256+r;
     for(int k=i+1;k<nt-1;k++){memcpy(tk[k],tk[k+1],64);tl[k]=tl[k+1];id[k]=id[k+1];}
     nt--;f=1;break;
    }
  if(!f)break;
 }
 for(int i=0;i<nt;i++)out[(*no)++]=id[i];
}
int encode(char*s,int*tok){
 int n=0,len=strlen(s),i=0,st[N],le[N],m=0;
 while(i<len){
  int b=i;
  if(s[i]=='\''&&i+1<len){
   if(s[i+1]=='s'||s[i+1]=='t'||s[i+1]=='m'||s[i+1]=='d')i+=2;
   else if(i+2<len&&s[i+1]=='r'&&s[i+2]=='e')i+=3;
   else if(i+2<len&&s[i+1]=='v'&&s[i+2]=='e')i+=3;
   else if(i+3<len&&s[i+1]=='l'&&s[i+2]=='l'&&s[i+3]=='d')i+=4;
   else i++;
  }else if(s[i]==' '&&i+1<len&&(isA(s[i+1])||isD(s[i+1]))){
   i++;while(i<len&&(isA(s[i])||isD(s[i])))i++;
  }else if(s[i]==' '&&i+1<len&&!isS(s[i+1])){
   i++;while(i<len&&!isS(s[i]))i++;
  }else if(isA(s[i])||isD(s[i])){
   while(i<len&&(isA(s[i])||isD(s[i])))i++;
  }else if(!isS(s[i])){
   while(i<len&&!isS(s[i]))i++;
  }else{
   while(i<len&&isS(s[i]))i++;
  }
  st[m]=b;le[m]=i-b;m++;
  if(m>=N-25)break;
 }
 for(int j=0;j<m;j++)bpe(s+st[j],le[j],tok,&n);
 return n;
}
void out_tok(int id){
 char*s=voc[id];int l=vl[id],i=0;
 while(i<l){
  int cp;
  if(s[i]<128){cp=s[i];i++;}
  else{cp=((s[i]&0x1F)<<6)|(s[i+1]&0x3F);i+=2;}
  int b;
  if(cp>=33&&cp<=126)b=cp;
  else if(cp>=161&&cp<=172)b=cp;
  else if(cp>=174&&cp<=255)b=cp;
  else if(cp>=256&&cp<=288)b=cp-256;
  else if(cp==289)b=127;
  else if(cp>=290&&cp<=322)b=cp-162;
  else if(cp==323)b=173;
  else b=cp;
  putchar(b);
 }
}
void ln(float*o,float*x,float*g,float*b){
 float m=0,v=0;
 for(int j=0;j<D;j++)m+=x[j];m/=D;
 for(int j=0;j<D;j++){float d=x[j]-m;v+=d*d;}
 v=sqrtf(v/D+1e-5f);
 for(int j=0;j<D;j++)o[j]=(x[j]-m)/v*g[j]+b[j];
}
void mm(float*o,float*x,float*w,float*b,int d,int k){
 for(int j=0;j<d;j++){float s=b?b[j]:0;for(int p=0;p<k;p++)s+=x[p]*w[p*d+j];o[j]=s;}
}
void fwd(int pos){
 float xn[D],q[3*D],a[D],pr[D],xn2[D],h[FC],h2[D];
 for(int l=0;l<L;l++){
  ln(xn,x+pos*D,lw[l][5],lw[l][4]);
  mm(q,xn,lw[l][1],lw[l][0],3*D,D);
  memcpy(kc[l]+pos*D,q+D,D*4);
  memcpy(vc[l]+pos*D,q+2*D,D*4);
  for(int hh=0;hh<H;hh++){
   float sc[N],mx=-1e9f;
   for(int j=0;j<=pos;j++){
    float s=0;
    for(int d=0;d<HD;d++)s+=q[hh*HD+d]*kc[l][j*D+hh*HD+d];
    s*=0.125f;sc[j]=s;if(s>mx)mx=s;
   }
   float sm=0;
   for(int j=0;j<=pos;j++){sc[j]=expf(sc[j]-mx);sm+=sc[j];}
   for(int d=0;d<HD;d++){float v=0;for(int j=0;j<=pos;j++)v+=sc[j]/sm*vc[l][j*D+hh*HD+d];a[hh*HD+d]=v;}
  }
  mm(pr,a,lw[l][3],lw[l][2],D,D);
  for(int j=0;j<D;j++)x[pos*D+j]+=pr[j];
  ln(xn2,x+pos*D,lw[l][7],lw[l][6]);
  mm(h,xn2,lw[l][9],lw[l][8],FC,D);
  for(int j=0;j<FC;j++){float t=h[j];h[j]=0.5f*t*(1.f+tanhf(.7978845608f*(t+.044715f*t*t*t)));}
  mm(h2,h,lw[l][11],lw[l][10],D,FC);
  for(int j=0;j<D;j++)x[pos*D+j]+=h2[j];
 }
}
int main(int argc,char**argv){
 if(argc<4)return 1;
 load_bpe(argv[2]);
 C=malloc(124439808*4);
 FILE*f=fopen(argv[1],"rb");
 fread(C,4,124439808,f);fclose(f);
 float*p=C;
 for(int l=0;l<L;l++){
  lw[l][0]=p;p+=D;lw[l][1]=p;p+=3*D*D;lw[l][2]=p;p+=D;
  lw[l][3]=p;p+=D*D;lw[l][4]=p;p+=D;lw[l][5]=p;p+=D;
  lw[l][6]=p;p+=D;lw[l][7]=p;p+=D;lw[l][8]=p;p+=FC;
  lw[l][9]=p;p+=FC*D;lw[l][10]=p;p+=D;lw[l][11]=p;p+=D*D;
 }
 lf_b=p;p+=D;lf_g=p;p+=D;we=p;p+=V*D;pe=p;
 int tok[N];
 int nt=encode(argv[3],tok);
 if(nt<1)return 0;
 if(nt>N-21)nt=N-21;
 x=calloc(N*D,4);
 for(int l=0;l<L;l++){kc[l]=calloc(N*D,4);vc[l]=calloc(N*D,4);}
 for(int i=0;i<nt;i++)for(int j=0;j<D;j++)x[i*D+j]=we[tok[i]*D+j]+pe[i*D+j];
 for(int i=0;i<nt;i++)fwd(i);
 for(int t=0;t<20&&nt<N;t++){
  float xn[D];
  ln(xn,x+(nt-1)*D,lf_g,lf_b);
  int best=0;float lm=0;
  for(int d=0;d<D;d++)lm+=xn[d]*we[d];
  for(int j=1;j<V;j++){float s=0;for(int d=0;d<D;d++)s+=xn[d]*we[j*D+d];if(s>lm){lm=s;best=j;}}
  out_tok(best);
  tok[nt]=best;nt++;
  if(nt>=N)break;
  int i=nt-1;
  for(int j=0;j<D;j++)x[i*D+j]=we[best*D+j]+pe[i*D+j];
  fwd(i);
 }
 putchar('\n');
 return 0;
}
